-- Torts: Intentional Torts, Negligence, Strict Liability, Products Liability, Defamation, Nuisance, Damages
-- 25 MBE questions

BEGIN;

INSERT INTO quiz_questions
  (subject_id, category, difficulty, stem,
   option_a, option_b, option_c, option_d,
   correct_answer, explanation, rule_tested, case_citation, is_active)
VALUES
  ('torts-001','intentional_torts','easy','Battery requires:',
   'An intent to cause harmful or offensive contact and actual physical harm.','An intent to cause harmful or offensive contact, which results in such contact.','Deliberate violence against another person.','Offensive words or threats causing apprehension.',
   'B','Battery: (1) intent to cause harmful or offensive contact, and (2) harmful or offensive contact results. Intent to make contact is required, not intent to harm. Contact with the person or something closely connected to the person (e.g., clothing, a cane) qualifies. Damages are presumed.','Battery — Elements',null, true),
  ('torts-001','intentional_torts','medium','Assault requires:',
   'Physical contact with the plaintiff.','Intent to cause apprehension, and reasonable apprehension of imminent harmful or offensive contact.','Words threatening future harm.','A weapon or other dangerous instrumentality.',
   'B','Assault: (1) intent to cause apprehension, (2) reasonable apprehension of imminent harmful or offensive contact. Words alone generally cannot constitute assault (no apprehension of physical contact); physical contact itself is battery, not assault. The plaintiff must be aware of the threatened contact.','Assault — Elements',null, true),
  ('torts-001','intentional_torts','medium','False imprisonment requires:',
   'Imprisonment in a jail or correctional facility.','Intent to confine, and actual confinement in a bounded area that the plaintiff is aware of or harmed by.','An unlawful arrest by law enforcement.','Confinement for more than one hour.',
   'B','False imprisonment: (1) intent to confine, (2) actual confinement within a bounded area, and (3) plaintiff is aware of or harmed by the confinement. There must be no reasonable means of escape that the plaintiff can use without danger, hardship, or affront to dignity.','False Imprisonment — Elements',null, true),
  ('torts-001','intentional_torts','hard','Shopkeeper''s privilege allows a merchant to detain a suspected shoplifter if:',
   'The merchant has reasonable grounds to believe shoplifting occurred, detains in a reasonable manner, and for a reasonable time to investigate.','Any store employee suspects theft.','The suspect is caught on camera.','Law enforcement has been called.',
   'A','The shopkeeper''s privilege (Restatement § 120A): a shopkeeper may detain a suspected shoplifter if (1) there are reasonable grounds to believe theft occurred or is occurring, (2) detention is done in a reasonable manner (not excessive force), and (3) only for a reasonable time necessary to investigate or summon police.','Shopkeeper''s Privilege',null, true),
  ('torts-001','intentional_torts','medium','Intentional infliction of emotional distress (IIED) requires:',
   'Any intentional emotional harm.','Extreme and outrageous conduct, intent (or recklessness) to cause severe emotional distress, and severe emotional distress results.','Physical contact causing emotional trauma.','Repeated harassment over a period of time.',
   'B','IIED (Restatement § 46): (1) extreme and outrageous conduct (exceeds all bounds tolerated by decent society), (2) intent to cause severe emotional distress or reckless disregard of high probability of causing it, and (3) causation of severe emotional distress. ''Extreme and outrageous'' is a high bar.','IIED — Elements',null, true),
  ('torts-001','intentional_torts','hard','A defendant with intent to commit battery against A accidentally hits B instead. Under the doctrine of transferred intent:',
   'Defendant has no liability to B — there was no intent to contact B.','Intent to commit battery against A transfers to B — defendant is liable for battery against B.','Defendant is liable only for negligence toward B.','Defendant is liable to A for battery but not to B.',
   'B','Transferred intent: when a defendant intends to commit an intentional tort against one person but the tort occurs against a different person, the intent transfers. Traditional torts for which intent transfers include: battery, assault, false imprisonment, trespass to land, and trespass to chattels.','Transferred Intent',null, true),
  ('torts-001','negligence','easy','The elements of negligence are:',
   'Intent, causation, and damages.','Duty, breach, causation (actual and proximate), and damages.','Strict liability, causation, and harm.','Knowledge of the risk, unreasonable conduct, and injury.',
   'B','Negligence requires: (1) a duty of care owed to the plaintiff, (2) breach of that duty (conduct falling below the reasonable person standard), (3) actual causation (but-for cause), (4) proximate causation (legal cause/foreseeability), and (5) actual damages. All five elements must be proven.','Negligence — Elements',null, true),
  ('torts-001','negligence','medium','The reasonable person standard in negligence is:',
   'The standard of a similarly trained professional.','What an ordinarily prudent person would do in similar circumstances.','What the defendant believed was appropriate.','A standard adjusted for the defendant''s subjective mental state.',
   'B','The objective reasonable person standard: negligence is judged by what a hypothetical reasonable person (average intelligence, reasonable knowledge and skill) would do under the same or similar circumstances. Defendants are not judged by their individual capacity — those below average are still held to the reasonable person standard.','Reasonable Person Standard',null, true),
  ('torts-001','negligence','hard','A professional (e.g., a doctor) is held to:',
   'The ordinary reasonable person standard.','The standard of a reasonably competent member of the same profession under similar circumstances.','The highest degree of care technically possible.','A standard set by licensing boards.',
   'B','Professionals are held to the standard of a reasonably competent member of their profession (specialty) in similar circumstances, not merely the reasonable layperson. Medical specialists are held to the standard of their specialty, not general practitioners.','Professional Standard of Care',null, true),
  ('torts-001','negligence','medium','Res ipsa loquitur allows a plaintiff to prove negligence circumstantially if:',
   'The plaintiff cannot identify the specific negligent act.','The accident is of a type that does not normally occur without negligence, the instrumentality was within the defendant''s exclusive control, and the plaintiff did not contribute.','The plaintiff suffered a severe injury.','The defendant cannot explain how the accident occurred.',
   'B','Res ipsa loquitur (the thing speaks for itself): permits an inference of negligence when (1) the event is of a type that normally does not occur absent negligence, (2) the defendant had exclusive control over the instrumentality, and (3) the plaintiff did not contribute to the occurrence. It shifts the burden of production, not persuasion.','Res Ipsa Loquitur — Elements',null, true),
  ('torts-001','negligence','hard','The ''but for'' test of actual causation means:',
   'The defendant''s negligence was a proximate cause of the injury.','The plaintiff would not have been injured but for the defendant''s negligent conduct.','The negligent act was the most significant cause of the injury.','Multiple actors contributed to the injury.',
   'B','Actual (factual) causation is established by the but-for test: plaintiff must prove that but for the defendant''s negligent conduct, the harm would not have occurred. When multiple defendants each independently caused sufficient harm, the substantial factor test may be used.','Actual Causation — But-For Test',null, true),
  ('torts-001','negligence','medium','In Palsgraf v. Long Island Railroad, the court held that a defendant owes a duty of care only to:',
   'Everyone who might foreseeably be injured by negligent conduct.','Those who are in the foreseeable zone of danger from the defendant''s negligent conduct.','Anyone the defendant could have seen at the time of the act.','Those who have a pre-existing relationship with the defendant.',
   'B','Cardozo''s majority in Palsgraf: the defendant owes a duty only to those within the foreseeable zone of danger — those foreseeably at risk from the specific negligent act. Mrs. Palsgraf was too far from the trainmen''s negligent act to be a foreseeable plaintiff. Andrews'' dissent argued duty runs to all.','Proximate Causation — Palsgraf / Zone of Danger',"Palsgraf v. Long Island Railroad Co. (1928)", true),
  ('torts-001','negligence','hard','A superseding cause:',
   'Is any intervening act that breaks the causal chain.','Is an intervening cause that was not foreseeable and that breaks the original defendant''s liability.','Is only relevant when a third party acts intentionally.','Is any intervening cause that contributed to the plaintiff''s injury.',
   'B','An intervening cause breaks the chain of proximate causation only if it is unforeseeable (superseding). Foreseeable intervening causes (rescue attempts, ordinary negligence of others, medical malpractice) do not relieve the original defendant. Criminal acts of third parties may be superseding unless their occurrence was foreseeable.','Superseding Cause',null, true),
  ('torts-001','negligence','medium','Comparative fault replaces the common law contributory negligence rule by:',
   'Barring recovery if the plaintiff is more than 50% at fault.','Reducing the plaintiff''s recovery proportionally to her share of fault.','Allocating fault equally between the parties.','Eliminating all damages when the plaintiff was partially at fault.',
   'B','Pure comparative fault (minority of states): plaintiff''s recovery is reduced by her percentage of fault, no matter how great. Modified comparative fault (most states): plaintiff may recover only if her fault does not exceed 50% (or 51%) of the total. Both replace the all-or-nothing contributory negligence bar.','Comparative Fault — Replacing Contributory Negligence',null, true),
  ('torts-001','strict_liability','easy','A defendant engaged in an abnormally dangerous activity is liable for resulting harm:',
   'Only if negligent in how the activity was conducted.','Without proof of negligence, based on strict liability.','Only to adjacent landowners.','Only if the activity violated a statute.',
   'B','Strict liability for abnormally dangerous activities (Restatement § 520): the defendant is liable without proof of negligence if the activity (1) involves serious risk of harm, (2) cannot be made safe even with utmost care, (3) is not common usage, (4) is inappropriate for the location, and (5) the risk outweighs the utility.','Strict Liability — Abnormally Dangerous Activities',null, true),
  ('torts-001','strict_liability','medium','Under Rylands v. Fletcher, a defendant who brings onto land a dangerous substance that escapes and harms another is:',
   'Liable only if negligent.','Strictly liable for all natural consequences of the escape.','Liable only if the substance was inherently dangerous.','Not liable if the escape was caused by an act of God.',
   'B','Rylands v. Fletcher established the English predecessor to strict liability for dangerous instrumentalities. A person who brings onto land a dangerous substance that is likely to do harm if it escapes is strictly liable if it escapes and causes damage. American courts adopted this rule for ultra-hazardous activities.','Rylands v. Fletcher — Strict Liability',"Rylands v. Fletcher (1868)", true),
  ('torts-001','products_liability','easy','Under strict products liability (Restatement § 402A), a manufacturer is liable for:',
   'Any injury caused by its product.','A product that is defective and unreasonably dangerous when it leaves the seller''s control.','A product the buyer did not use as intended.','Breach of an express warranty only.',
   'B','Restatement (Second) § 402A: a seller who sells a product in a defective condition unreasonably dangerous to the user or consumer is strictly liable for physical harm caused to the ultimate user, even if the seller exercised all possible care and there is no contractual privity between them.','Strict Products Liability — § 402A',"Restatement (Second) of Torts § 402A", true),
  ('torts-001','products_liability','medium','A manufacturing defect exists when:',
   'The product''s design makes it unreasonably dangerous.','A specific unit departs from the intended design and is thereby more dangerous.','The product lacks adequate warnings.','The product fails to meet consumer expectations.',
   'B','A manufacturing defect: the product as made differs from the intended design. It makes an individual product unit more dangerous than it should have been — a departure from the manufacturer''s own specifications. The plaintiff must show the specific unit deviated from the design.','Manufacturing Defect',null, true),
  ('torts-001','products_liability','hard','Under the risk-utility test for design defects, a product is defectively designed if:',
   'The product injured the plaintiff.','The foreseeable risks of harm posed by the product could have been reduced by a reasonable alternative design whose omission renders the product not reasonably safe.','The product did not meet industry standards.','The product failed to include warnings.',
   'B','Restatement (Third) of Torts § 2(b) adopts the risk-utility test for design defects: a product is defectively designed if the foreseeable risks of harm could have been reduced or avoided by a reasonable alternative design (RAD) and the omission of the RAD renders the product not reasonably safe. This requires proof of a feasible alternative.','Design Defect — Risk-Utility Test / RAD',"Restatement (Third) of Torts § 2(b)", true),
  ('torts-001','defamation','easy','Defamation requires:',
   'A false statement.','A false statement of fact, published to a third party, that harms the plaintiff''s reputation.','A harmful opinion.','Malicious intent.',
   'B','Defamation (libel/slander) requires: (1) a false statement of fact (not opinion), (2) publication to at least one third party, (3) identification of the plaintiff, (4) fault (at least negligence for private plaintiffs per Gertz), and (5) damages (presumed for libel per se; required for slander without the per se exceptions).','Defamation — Elements',null, true),
  ('torts-001','defamation','medium','A public figure suing for defamation must prove:',
   'Negligence.','Actual malice — knowledge of falsity or reckless disregard for truth or falsity.','Intentional harm.','That the defendant acted with ill will.',
   'B','Under New York Times Co. v. Sullivan, a public official (and by extension, public figure) must prove actual malice — the defendant knew the statement was false or acted with reckless disregard for its truth or falsity. This First Amendment-based standard protects robust public debate.','Defamation — Public Figure / Actual Malice',"New York Times Co. v. Sullivan (1964)", true),
  ('torts-001','nuisance','easy','Private nuisance is defined as:',
   'Any annoying or bothersome activity by a neighbor.','An intentional, negligent, or abnormally dangerous act that substantially and unreasonably interferes with another''s use and enjoyment of their property.','Any action that reduces the plaintiff''s property value.','Conduct that violates local zoning laws.',
   'B','Private nuisance: a substantial and unreasonable interference with another''s use and enjoyment of land. ''Substantial'' means more than mere annoyance; ''unreasonable'' requires balancing the utility of the conduct against the gravity of the harm.','Private Nuisance — Elements',null, true),
  ('torts-001','nuisance','medium','Public nuisance is an act that:',
   'Affects only adjacent landowners.','Unreasonably interferes with a right common to the general public.','Is illegal under local ordinance.','Is a persistent trespass to public land.',
   'B','Public nuisance: an unreasonable interference with a right common to the general public — e.g., blocking a public road, contaminating a public water supply, or creating conditions endangering public health or safety. A private person may sue for public nuisance only by showing special harm different in kind from that suffered by the public.','Public Nuisance — Elements',null, true),
  ('torts-001','damages_torts','easy','Compensatory damages in tort law are designed to:',
   'Punish the defendant.','Make the plaintiff whole by compensating for actual losses.','Deter future misconduct.','Cover only economic losses.',
   'B','Compensatory damages aim to restore the plaintiff to the position they would have been in but for the tort. They include special (economic) damages — medical expenses, lost wages, property damage — and general (non-economic) damages — pain and suffering, emotional distress, loss of enjoyment of life.','Compensatory Damages — Goal',null, true),
  ('torts-001','damages_torts','hard','Punitive damages in tort cases are awarded when:',
   'The plaintiff suffers severe injuries.','The defendant''s conduct was intentional, malicious, fraudulent, or so reckless as to show conscious disregard for the rights of others.','Economic damages are very high.','The defendant is a large corporation.',
   'B','Punitive damages are awarded in addition to compensatory damages to punish and deter egregious misconduct. They require a finding that the defendant acted with malice, fraud, oppression, or reckless disregard for others'' rights. Due process limits their amount relative to compensatory damages (BMW v. Gore).','Punitive Damages — Standard',"BMW of North America v. Gore (1996)", true);

COMMIT;
